@Component
struct WarehouseAccumulator {
  @State total: number = 0
  private rows: StockRow[] = []
  refresh() {
    this.total = 0
    this.rows.forEach((row: StockRow) => {
      this.total += row.quantity
    })
  }
  build() { Text(`${this.total}`) }
}

